//! # My Crate
//!
//! `my_crate` is a collection of utilities to make performing certain
//! calculations more convenient.

/// Adds one to the number given.
///
/// # Examples
///
/// ```
/// let arg = 5;
/// let answer = my_crate::add_one(arg);
///
/// assert_eq!(6, answer);
/// ```
pub fn add_one(x: i32) -> i32 {
    x + 1
}

blocks.md:
The module structure that is convenient for **you** while writing a crate is often not convenient for **users**. *The Rust Programming Language* has an `art` crate with types in `art::kinds` and functions in `art::utils`. Users would have to write:

```rust
use art::kinds::PrimaryColor;
use art::utils::mix;
```

They must know your internal layout, and the front page of the docs shows only two modules. **Re-exporting** with `pub use` at the top level fixes both, without moving any code:

blocks.code:
//! # Art
//!
//! A library for modeling artistic concepts.

pub use self::kinds::PrimaryColor;
pub use self::kinds::SecondaryColor;
pub use self::utils::mix;

pub mod kinds {
    /// The primary colors according to the RYB color model.
    pub enum PrimaryColor {
        Red,
        Yellow,
        Blue,
    }

    /// The secondary colors according to the RYB color model.
    pub enum SecondaryColor {
        Orange,
        Green,
        Purple,
    }
}

pub mod utils {
    use crate::kinds::*;

    /// Combines two primary colors in equal amounts to create
    /// a secondary color.
    pub fn mix(c1: PrimaryColor, c2: PrimaryColor) -> SecondaryColor {
        // --snip--
        SecondaryColor::Orange
    }
}

mod shapes {
    // add re-exports here

    pub mod kinds {
        pub struct Circle {
            pub r: f64,
        }
    }

    pub mod math {
        use super::kinds::Circle;

        pub fn area(c: &Circle) -> f64 {
            std::f64::consts::PI * c.r * c.r
        }
    }
}

fn main() {
    let c = shapes::Circle { r: 5.0 };
    println!("{:.2}", shapes::area(&c));
}
